{
  "technical_and_design_decisions": [
    "Target platform is a Spring XD-style distributed runtime with custom modules packaged as uber-jars; baseline is Spring Framework 6 on Java 17 per the specification.",
    "U2: Host custom module uber-jars in a dedicated HDFS directory (e.g., /xd/modules) accessed via the Hadoop HDFS client; newly arriving containers resolve and download modules from HDFS into a local cache before classloading.",
    "U3: Implement the WebSocket sink as a native sink module built on spring-websocket, exposing full-duplex channels over a single TCP connection with configurable port, path, and message codecs.",
    "U8: Shared dependencies are placed under xd/lib and loaded by a shared parent classloader; modules requiring conflicting versions must embed those jars in their uber-jar to isolate them from the shared classloader.",
    "U4/U5: CI builds remain Gradle-based via the Gradle wrapper (./gradlew); the Artifactory Gradle plugin task is replaced by a command task; npm-cache is evaluated and, if adopted, integrated to cache Node dependencies.",
    "U6: Static analysis is centralized in SonarQube with quality gates; committer notifications are configured through SonarQube/CI hooks tied to the commit author.",
    "U7: Windows integration tests run on a Bamboo agent on the existing Bamboo Windows server using PowerShell scripts; required services (Redis, RabbitMQ) are installed as Windows services and started by the CI task.",
    "Testing approach: unit tests with JUnit, integration tests against embedded/minicluster Hadoop where feasible, plus end-to-end CI validation jobs on EC2 and Windows."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are in ideal workdays (8 hours each) and represent effort, not elapsed calendar time.",
    "An existing Spring XD-like codebase with module deployment, containers, and the xd/lib directory already exists and is the baseline for this increment.",
    "Access to an HDFS cluster (or Hadoop minicluster for tests), EC2 CI infrastructure, a Bamboo server with a Windows agent, and PowerShell is already available without procurement effort.",
    "npm-cache is relevant only to portions of the build that use npm (front-end assets); the evaluation will confirm applicability before adoption.",
    "The WebSocket sink is a stream sink module only; no user interface work is required.",
    "Documentation (U1) is delivered as markdown/asciidoc within the project repository, including module packaging, HDFS deployment, and xd/lib guidance.",
    "U8 requires implementing/verifying shared xd/lib loading behavior plus documented guidance for version conflicts, not a redesign of the module classloader.",
    "Existing test suites are functional; effort includes fixing only the PMD/Sonar violations related to the WARN log increase, not a full codebase cleanup.",
    "Infrastructure accounts, licenses, and credentials (SonarQube, Artifactory, Bamboo, cloud) are pre-provisioned."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Author custom module development documentation (U1)",
      "activity_description": "Write developer-facing documentation describing recommended standards and patterns for building custom modules, including project layout, packaging as uber-jar, and references to xd/lib and HDFS deployment.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Design and implement HDFS hosting of module uber-jars (U2)",
      "activity_description": "Implement HDFS-based storage for custom module uber-jars: directory layout, upload/publish path, configuration properties, and module metadata handling using the Hadoop HDFS client.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement module deployment to newly arriving containers (U2)",
      "activity_description": "Implement resolution and distribution of modules from HDFS to newly arriving containers, including local caching, version handling, and integration with the module classloading lifecycle.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "Test HDFS module hosting and deployment (U2)",
      "activity_description": "Write and execute unit and integration tests for HDFS hosting and container deployment, using a Hadoop minicluster where appropriate, and verify failure/retry scenarios.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement native WebSocket sink module (U3)",
      "activity_description": "Design and implement the WebSocket sink module on spring-websocket, providing full-duplex communication over a single TCP connection with configurable endpoint, port, and message handling.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Test WebSocket sink module (U3)",
      "activity_description": "Write and run unit and integration tests for the WebSocket sink, covering connection lifecycle, concurrent clients, message delivery, and error handling.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Research CI dependency caching options (U4)",
      "activity_description": "Spike npm-cache and comparable caching options, assess applicability to the current build, and produce a recommendation for improving CI build stability and reliability.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8",
      "activity_name": "Integrate selected caching option into CI build (U4)",
      "activity_description": "Implement and validate the chosen caching solution (e.g., npm-cache) in the CI build so dependencies are reused across builds instead of being downloaded each time.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Enable distributed JVM tests on EC2 CI (U5)",
      "activity_description": "Configure and validate distributed JVM test execution in the EC2 CI infrastructure.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "Replace Artifactory Gradle task with wrapper command task (U5)",
      "activity_description": "Change CI build configuration from the Artifactory Gradle task to a command task that invokes ./gradlew, and update publishing steps accordingly.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "Run CI tests with embedded Hadoop disabled (U5)",
      "activity_description": "Adjust test configuration to run with embedded Hadoop off, fix resulting test/environment issues, and verify suite stability.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Enable and tune maxParallelForks (U5)",
      "activity_description": "Turn on maxParallelForks for Gradle test execution, tune fork counts for EC2 agents, and confirm build time and stability improvements.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A13",
      "activity_name": "Validate EC2 CI pipeline end-to-end (U5)",
      "activity_description": "Run full commit-triggered builds on EC2 with all U5 changes applied and confirm reliable execution and functional assertions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A14",
      "activity_name": "Investigate WARN log increase (U6)",
      "activity_description": "Analyze build/test logs to identify root causes of the increased WARN entries and map them to PMD/Sonar violations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A15",
      "activity_name": "Fix PMD/Sonar violations (U6)",
      "activity_description": "Remediate the identified PMD and Sonar violations in the codebase and verify that WARN output returns to expected levels.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A16",
      "activity_name": "Configure Sonar committer notifications (U6)",
      "activity_description": "Configure SonarQube/CI notification rules so that the committer responsible for new violations is automatically notified.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A17",
      "activity_name": "Provision Windows Bamboo environment and PowerShell access (U7)",
      "activity_description": "Gain access to the existing Bamboo Windows environment, configure the agent, and verify PowerShell execution capabilities for CI tasks.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A18",
      "activity_name": "Install and configure Windows services (U7)",
      "activity_description": "Set up required services (Redis, RabbitMQ, and similar) on the Windows CI environment with automated start/stop scripts.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A19",
      "activity_name": "Create Windows integration test CI task (U7)",
      "activity_description": "Implement the Bamboo CI task that runs integration tests on Windows automatically on commit-triggered builds.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A20",
      "activity_name": "Stabilize and validate Windows CI runs (U7)",
      "activity_description": "Execute repeated Windows CI runs, fix environment-specific failures, and confirm consistent automated integration test results.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A21",
      "activity_name": "Implement shared xd/lib dependency location (U8)",
      "activity_description": "Implement/verify support for placing jars shared by two or more modules under xd/lib, including classloader behavior and documented guidance for bundling conflicting versions inside module uber-jars.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A22",
      "activity_name": "Test shared library scenarios (U8)",
      "activity_description": "Test multi-module deployments using xd/lib, including shared jars and modules bundling older/newer versions to work around classloader conflicts.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A23",
      "activity_name": "Increment integration, regression testing, and release preparation",
      "activity_description": "Integrate all stories, run full regression suites across CI environments, finalize documentation updates, and prepare the software increment for release.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 74
  }
}
